                              customer_id=customer_id, actor_id=actor_id, event_id=event_id,
                              message=message, expected_version=expected_version, resume_route=resume_route,
                              resume_prepare=resume_prepare)

async def _resume(self, *, tenant_id: str, case_id: UUID, token: str | None,
                  actor_id: str, event_id: str | None, message: str | None,
                  expected_version: int | None, customer_id: UUID | None = None,
                  resume_route: ResumeRoute | None = None,
                  resume_prepare: ResumePrepare | None = None) -> dict[str, Any]:
    if message is not None and not message.strip():
        raise ValueError("customer input must not be blank")
    safe_message = masked(message.strip()) if message is not None else None
    message_hash = self.case_service.token_hash(message.strip()) if message is not None else None
    with self.connection_factory() as conn:
        # 같은 업무의 토큰 검증과 소비는 행 잠금 안에서 처리한다.
        # 읽기 뒤 버전만 재시도하면 다른 답변이 사용한 토큰을 다시 소비할 수 있다.
        with conn.cursor() as cur:
            cur.execute("SELECT 1 FROM customer_cases WHERE tenant_id=%s AND case_id=%s FOR UPDATE",
                        (tenant_id, case_id))
        case = self.repository.get_case(conn, tenant_id=tenant_id, case_id=case_id)
        if case is None:
            raise ControllerError("case not found")
        if token is None and (customer_id is None or str(case["customer_id"]) != str(customer_id)):
            raise ControllerError("customer does not own case")
        try:
            validation = (self.case_service.validate_resume(case, token, event_id=event_id,
                                                             message_hash=message_hash) if token is not None
                          else self.case_service.validate_customer_input(case, event_id=event_id,
                                                                          message_hash=message_hash))
            if validation == "idempotent":
                # 입력 반영 뒤 실행 시작 전에 중단되거나 실행이 실패한 업무를 이어간다.
                # 행 잠금을 먼저 풀어 다음 실행의 짧은 트랜잭션을 막지 않는다.
                if case["status"] in {CaseStatus.RUNNING, CaseStatus.RESUMING}:
                    with conn.cursor() as cur:
                        cur.execute("SELECT 1 FROM agent_runs WHERE tenant_id=%s AND case_id=%s "
                                    "AND status IN ('active','running','resuming') LIMIT 1",
                                    (tenant_id, case_id))
                        active = cur.fetchone() is not None
                    if not active:
                        self.require_team(case.get("owner_team_id"), case_id=case_id)
                        conn.rollback()
                        try:
                            return await self.run_case(tenant_id=tenant_id, case_id=case_id, actor_id=actor_id)
                        except ActiveRunError:
                            # 같은 재시도가 먼저 시작된 경우 완료라고 하지 않고 현재 상태를 돌려준다.
                            latest = self.repository.get_case(conn, tenant_id=tenant_id, case_id=case_id) or case
                            return {"case_id": str(case_id), "status": latest["status"],
                                    "version": latest["version"], "idempotent": True}
                return {"case_id": str(case_id), "status": case["status"],
                        "version": case["version"], "idempotent": True}
        except ResumeRequestConflict as exc:
            raise StateConflict(str(exc)) from exc
        except ResumeTokenExpired as exc:
            self.require_team(case.get("owner_team_id"), case_id=case_id)
            try:
                with conn.transaction():
                    transition_case(conn, tenant_id=tenant_id, case_id=case_id,
                                    expected_version=case["version"], event_type=EventType.WAIT_EXPIRED,
                                    payload={"wait_reason": self._wait_reason(case)},
                                    actor_type="controller", actor_id=actor_id)
                conn.commit()
            except InvalidTransition:
                logger.warning("stale resume token ignored for terminal/non-waiting case",
                               extra={"tenant_id": tenant_id, "case_id": str(case_id)})
            raise ResumeExpiredError(str(exc)) from exc
        except ResumeTokenError as exc:
            logger.warning("stale resume token ignored; waiting state preserved",
                           extra={"tenant_id": tenant_id, "case_id": str(case_id)})
            raise ControllerError(str(exc)) from exc
        if expected_version is not None and expected_version != case["version"]:
            raise StateConflict("case version changed before customer input")
        self.require_team(case.get("owner_team_id"), case_id=case_id)
        state = case.get("state_json") or {}
        token_hash = self.case_service.token_hash(token) if token is not None else state["resume_token_hash"]
        patch = {"resume_token_used": True, "last_resume_event_id": event_id}
        if safe_message is not None:
            patch["customer_input"] = safe_message
            patch["customer_input_history"] = [*state.get("customer_input_history", []), safe_message]
        if event_id:
            patch["resume_requests"] = [*state.get("resume_requests", []), {
                "request_id": event_id, "message_hash": message_hash,
                "token_hash": token_hash,
            }]
        # 행 잠금 안에서 최종 담당을 먼저 정한다. 실행 불가 시 답변과 토큰을 소비하지 않는다.
        prospective = {**case, "status": CaseStatus.RESUMING, "state_json": {**state, **patch}}
        team_id = case.get("owner_team_id")
        route_patch = {}
        if resume_route is not None and safe_message is not None:
            routing = resume_route(prospective, safe_message)
            if isinstance(routing, dict):
                team_id = routing.get("owner_team_id") or team_id
                route_patch = routing.get("state_patch", {})
                if not isinstance(route_patch, dict):
                    raise ValueError("resume route state patch must be an object")
                allowed = set(self.TEAM_STATE_KEYS) - {"customer_input", "customer_input_history"}
                if set(route_patch) - allowed:
                    raise ValueError("resume route cannot change controller metadata")
            elif routing is not None:
                team_id = routing
        if team_id is not None and not isinstance(team_id, str):
            raise ValueError("resume route owner must be a team id")
        entry = self.require_team(team_id, case_id=case_id)
        routed_case = {**prospective, "state_json": {**prospective["state_json"], **route_patch}}
        capability = self.registry.capability_for(
            entry, case.get("intent"), input_text=safe_message,
            state=self._capability_state(routed_case))
        self.require_team(team_id, capability, case_id=case_id)
        if resume_prepare is not None and safe_message is not None:
            resume_prepare({**routed_case, "owner_team_id": team_id}, safe_message)
        try:
            with conn.transaction():
                transition_case(conn, tenant_id=tenant_id, case_id=case_id,
                                expected_version=case["version"], event_type=EventType.VALID_INPUT,
                                payload={"resume_token_hash": token_hash,
                                         "state_patch": patch}, actor_type="controller", actor_id=actor_id)
                if team_id != case.get("owner_team_id") or route_patch:
                    latest = self.repository.get_case(conn, tenant_id=tenant_id, case_id=case_id)
                    transition_case(conn, tenant_id=tenant_id, case_id=case_id,
                                    expected_version=latest["version"], event_type=EventType.ROUTED,
                                    payload={"owner_team_id": team_id, "capability": capability,
                                             "state_patch": route_patch},
                                    actor_type="controller", actor_id=actor_id)
                # 실행 입구가 RESUMED를 기록해야 TeamTask.resume/재개 지점도 맞는다.
            conn.commit()
        except InvalidTransition:
            logger.warning("stale resume transition ignored",
                           extra={"tenant_id": tenant_id, "case_id": str(case_id)})
            latest = self.repository.get_case(conn, tenant_id=tenant_id, case_id=case_id) or case
            return {"case_id": str(case_id), "status": latest["status"],
                    "version": latest["version"], "stale": True}
    return await self.run_case(tenant_id=tenant_id, case_id=case_id, actor_id=actor_id)

from datetime import datetime, timedelta, timezone
from types import SimpleNamespace
from uuid import uuid4

import pytest

from app.domains.travel_ops.components.conversation.decision_unit import Decision
from app.domains.travel_ops.components.conversation.fact_context import named_items, resolve

NOW = datetime(2030, 1, 1, tzinfo=timezone.utc)


def _item(name):
    return SimpleNamespace(item_id=uuid4(), title=name, kind="activity", place={"name": name})


def _decision(item=None, action="answer_fact"):
    return Decision(action=action, item=item, change=None, fact="detail", minutes=None, question="")


def _resolve(message="자세히 알려줘", **kw):
    first, second = _item("N서울타워"), _item("경복궁 관람")
    turns = [{"role": "assistant", "reply": {"focus": {"item_id": str(first.item_id), "version": 1, "at": NOW.isoformat()}}}]
    args = dict(items=[first, second], message=message, selected=None, turns=turns, version=1, now=NOW, ttl_seconds=1800)
    args.update(kw)
    return first, second, resolve(_decision(), **args)


@pytest.mark.parametrize("text", ["서울 타워 저거 뭐야?", "N 서울 타워 주소 알려줘", "n서울타워 상세 알려줘"])
def test_spacing_case_and_mixed_script_names(text):
    first, _, (decision, focus, stale) = _resolve(text)
    assert decision.item is first and focus["source"] == "message" and not stale


@pytest.mark.parametrize("text", ["자세히 알려줘", "거기 알려줘", "그거 자세히 알려 줘", "그건 뭐야?"])
def test_short_followup_uses_structured_previous_fact(text):
    first, _, (decision, focus, stale) = _resolve(text)
    assert decision.item is first and focus["source"] == "previous_fact" and not stale


@pytest.mark.parametrize("kw", [{"version": 2}, {"now": NOW + timedelta(minutes=31)}, {"now": NOW - timedelta(seconds=1)}, {"turns": []},
                              {"turns": [{"role": "assistant", "reply": {}}]}])
def test_version_time_and_unrelated_turn_invalidate_focus(kw):
    _, _, (decision, focus, _) = _resolve(**kw)
    assert decision.item is None and focus is None


@pytest.mark.parametrize("text", ["내일 자세히 알려줘", "2일차 상세 알려줘", "15:00 상세 알려줘", "다른 관광지 자세히 알려줘"])
def test_new_scope_does_not_inherit_old_target(text):
    _, _, (decision, focus, _) = _resolve(text)
    assert decision.item is None and focus is None


def test_unknown_id_and_write_actions_never_use_fact_focus():
    _, _, (decision, focus, stale) = _resolve(selected=uuid4())
    assert stale and decision.item is None and focus is None
    item = _item("경복궁")
    write = _decision(action="apply_change")
    assert resolve(write, items=[item], message="그거 바꿔", selected=None, turns=[], version=1, now=NOW, ttl_seconds=1800) == (write, None, False)


def test_names_shared_by_two_dates_are_ambiguous():
    items = [_item("경복궁"), _item("경복궁")]
    assert len(named_items(items, "경복궁 알려줘")) == 2


def test_bare_followup_uses_verified_focus_over_a_different_model_guess():
    first, second = _item("경복궁"), _item("서울숲")
    turns = [{"role": "assistant", "reply": {"focus": {"item_id": str(first.item_id), "version": 1, "at": NOW.isoformat()}}}]
    decision, focus, stale = resolve(_decision(second), items=[first, second], message="그거 자세히 알려줘",
                                    selected=None, turns=turns, version=1, now=NOW, ttl_seconds=1800)
    assert decision.item is first and focus["source"] == "previous_fact" and not stale


def test_model_guess_cannot_bypass_focus_expiry():
    item = _item("경복궁")
    turns = [{"role": "assistant", "reply": {"focus": {"item_id": str(item.item_id), "version": 1, "at": NOW.isoformat()}}}]
    decision, focus, stale = resolve(_decision(item), items=[item], message="자세히 알려줘", selected=None,
                                    turns=turns, version=2, now=NOW, ttl_seconds=1800)
    assert decision.item is None and focus is None and stale

"""초기 요청 재시도가 대기 답변·실행 중·미완료 상태를 대신하지 않도록 확인한다."""
from contextlib import nullcontext
from types import SimpleNamespace
from uuid import uuid4

import pytest

from app.core.contracts import StateConflict
from app.domains.travel_ops.components.conversation import case_dispatch


class Conn:
    def __init__(self, active=False):
        self.active = active
        self.commits = 0

    def cursor(self):
        return nullcontext(self)

    def execute(self, *args):
        pass

    def fetchone(self):
        return (1,) if self.active else None

    def commit(self):
        self.commits += 1


def call(monkeypatch, status, state=None, *, active=False, run_error=None):
    conn = Conn(active)
    case = dict(status=status, state_json=state or {}, intent="adjust", subject="점심 변경")
    monkeypatch.setattr(case_dispatch.repository, "get_case", lambda *a, **k: case)
    calls = []
    def run_case(**kwargs):
        calls.append(kwargs)
        if run_error is not None:
            raise run_error

    controller = SimpleNamespace(require_team=lambda *a, **k: object(),
        registry=SimpleNamespace(capability_for=lambda *a, **k: "change"),
        _capability_state=lambda c: c["state_json"], run_case=run_case)
    return conn, calls, lambda: case_dispatch.retry_initial(conn, controller=controller, tenant="travel-test",
        trip={"trip_id": "travel-test", "version": 1}, case_id=uuid4(), items=[], actor_id="test")


@pytest.mark.parametrize("status", ["new", "classifying", "resuming"])
def test_incomplete_request_is_conflict_instead_of_success_duplicate(monkeypatch, status):
    conn, calls, retry = call(monkeypatch, status)
    with pytest.raises(StateConflict, match="미완료 요청"):
        retry()
    assert not calls and conn.commits == 0


@pytest.mark.parametrize("status", ["waiting_input", "waiting_approval", "waiting_external", "resolved", "escalated", "failed", "cancelled"])
def test_waiting_or_terminal_case_keeps_existing_duplicate_policy(monkeypatch, status):
    conn, calls, retry = call(monkeypatch, status)
    assert retry() is None
    assert not calls and conn.commits == 0


@pytest.mark.parametrize("field", ["resume_requests", "customer_input_history"])
def test_initial_request_cannot_replace_an_in_progress_customer_reply(monkeypatch, field):
    conn, calls, retry = call(monkeypatch, "running", {field: ["합성 답변"]})
    with pytest.raises(StateConflict, match="원래 답변 요청"):
        retry()
    assert not calls and conn.commits == 0


@pytest.mark.parametrize("status", ["routing", "running"])
def test_old_incomplete_case_without_descriptor_requires_explicit_recovery(monkeypatch, status):
    conn, calls, retry = call(monkeypatch, status)
    with pytest.raises(StateConflict, match="저장된 실행 계획"):
        retry()
    assert not calls and conn.commits == 0


def test_active_run_is_never_replayed(monkeypatch):
    state = {"conversation_dispatch": {"team_id": "dining", "subject_ref": {
        "kind": "trip", "id": "travel-test", "base_version": 1, "request": {"action": "apply_change"}}}}
    conn, calls, retry = call(monkeypatch, "running", state, active=True)
    with pytest.raises(StateConflict, match="아직 실행 중"):
        retry()
